def R(src, names, cat, cuisine, type='dish', prepared='restaurant', state=None, aliases=None, portion=None, syn=None):
    return dict(src=src, names=names, cat=cat, cuisine=cuisine, type=type, prepared=prepared, state=state,
                aliases=aliases or {}, portion=portion, syn=syn or [])

